<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();

$role=(string)($_SESSION['role']??'');
$uid=(int)($_SESSION['user_id']??0);
if(!in_array($role,['system_admin','sub_admin','director'],true)){http_response_code(403);exit('You cannot access subscriptions.');}
$pdo=db();$error='';$notice='';$canEdit=$role==='system_admin';
if($role==='sub_admin'){$q=$pdo->prepare('SELECT active FROM subscription_price_permissions WHERE user_id=?');$q->execute([$uid]);$canEdit=(bool)$q->fetchColumn();}
$isSystem=$role==='system_admin';

if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='confirm_payment'){
            if(!$isSystem)throw new DomainException('Only system admins can confirm subscription payments.');$subscriptionId=(int)($_POST['subscription_id']??0);$pdo->beginTransaction();$q=$pdo->prepare("SELECT x.id,x.school_id,x.academic_year,x.pupil_count,x.unit_price,x.discount_percent,x.total_amount,p.currency,p.name plan_name,s.name school_name FROM subscriptions x JOIN subscription_prices p ON p.id=x.price_id JOIN schools s ON s.id=x.school_id WHERE x.id=? AND x.status='pending' FOR UPDATE");$q->execute([$subscriptionId]);$payment=$q->fetch(PDO::FETCH_ASSOC);if(!$payment)throw new DomainException('This subscription is no longer awaiting payment confirmation.');$q=$pdo->prepare("UPDATE subscriptions SET status='active' WHERE id=? AND status='pending'");$q->execute([$subscriptionId]);if($q->rowCount()!==1)throw new DomainException('The subscription status changed. Refresh and try again.');$q=$pdo->prepare('INSERT INTO audit_logs (actor_id,action,entity_type,entity_id,details) VALUES (?,?,?,?,?)');$q->execute([$uid,'payment_confirmed','subscription',$subscriptionId,json_encode(['school_id'=>(int)$payment['school_id'],'school'=>$payment['school_name'],'academic_year'=>(int)$payment['academic_year'],'plan'=>$payment['plan_name'],'currency'=>$payment['currency'],'pupil_count'=>(int)$payment['pupil_count'],'unit_price'=>(float)$payment['unit_price'],'discount_percent'=>(float)$payment['discount_percent'],'income'=>(float)$payment['total_amount']])]);$pdo->commit();header('Location: subscriptions.php?year='.(int)($_POST['year']??date('Y')).'&confirmed=1#income');exit;
        }
        if($action==='save_price'){
            if(!$canEdit)throw new DomainException('A system admin must grant you permission to manage subscription prices.');
            $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$currency=strtoupper(trim((string)($_POST['currency']??'KES')));$period=(string)($_POST['billing_period']??'yearly');$active=isset($_POST['active'])?1:0;
            if($name===''||strlen($name)>100||$amount===false||$amount<=0||!preg_match('/^[A-Z]{3}$/',$currency)||!in_array($period,['monthly','termly','yearly'],true))throw new DomainException('Enter a plan name, positive per-pupil price, three-letter currency, and valid billing period.');
            $pdo->beginTransaction();
            if($id){$q=$pdo->prepare('SELECT id,name,amount,currency,billing_period,active FROM subscription_prices WHERE id=? FOR UPDATE');$q->execute([$id]);$before=$q->fetch(PDO::FETCH_ASSOC);if(!$before)throw new DomainException('That subscription plan no longer exists.');$q=$pdo->prepare('UPDATE subscription_prices SET name=?,amount=?,currency=?,billing_period=?,active=? WHERE id=?');$q->execute([$name,$amount,$currency,$period,$active,$id]);$actionName='update';$details=['before'=>$before,'after'=>['name'=>$name,'amount'=>number_format((float)$amount,2,'.',''),'currency'=>$currency,'billing_period'=>$period,'active'=>(bool)$active]];}
            else{$q=$pdo->prepare('INSERT INTO subscription_prices (name,amount,currency,billing_period,active,created_by) VALUES (?,?,?,?,?,?)');$q->execute([$name,$amount,$currency,$period,$active,$uid]);$id=(int)$pdo->lastInsertId();$actionName='create';$details=['name'=>$name,'amount'=>number_format((float)$amount,2,'.',''),'currency'=>$currency,'billing_period'=>$period,'active'=>(bool)$active];}
            $q=$pdo->prepare('INSERT INTO audit_logs (actor_id,action,entity_type,entity_id,details) VALUES (?,?,?,?,?)');$q->execute([$uid,$actionName,'subscription_price',$id,json_encode($details,JSON_THROW_ON_ERROR)]);$pdo->commit();header('Location: subscriptions.php?saved='.$actionName);exit;
        }
        if($action==='permission'){
            if(!$isSystem)throw new DomainException('Only system admins can grant price management permission.');
            $target=(int)($_POST['user_id']??0);$grant=(string)($_POST['enabled']??'')==='1';$q=$pdo->prepare("SELECT id,name FROM users WHERE id=? AND role='sub_admin' AND status='active'");$q->execute([$target]);$person=$q->fetch(PDO::FETCH_ASSOC);if(!$person)throw new DomainException('Choose an active sub admin.');
            $pdo->beginTransaction();$q=$pdo->prepare('SELECT id,active FROM subscription_price_permissions WHERE user_id=? FOR UPDATE');$q->execute([$target]);$existing=$q->fetch(PDO::FETCH_ASSOC);
            if($grant){if($existing){$pdo->prepare('UPDATE subscription_price_permissions SET active=1,granted_by=?,granted_at=CURRENT_TIMESTAMP,revoked_at=NULL WHERE user_id=?')->execute([$uid,$target]);$permissionId=(int)$existing['id'];}else{$pdo->prepare('INSERT INTO subscription_price_permissions (user_id,granted_by) VALUES (?,?)')->execute([$target,$uid]);$permissionId=(int)$pdo->lastInsertId();}$auditAction='grant_subscription_price_edit';}
            else{if($existing){$pdo->prepare('UPDATE subscription_price_permissions SET active=0,revoked_at=CURRENT_TIMESTAMP WHERE user_id=?')->execute([$target]);$permissionId=(int)$existing['id'];}else{$permissionId=null;}$auditAction='revoke_subscription_price_edit';}
            $q=$pdo->prepare('INSERT INTO audit_logs (actor_id,action,entity_type,entity_id,details) VALUES (?,?,?,?,?)');$q->execute([$uid,$auditAction,'subscription_price_permission',$permissionId,json_encode(['user_id'=>$target,'name'=>$person['name'],'active'=>$grant])]);$pdo->commit();header('Location: subscriptions.php?permission='.($grant?'granted':'revoked'));exit;
        }
        if($action==='school_discount'){
            if(!$isSystem)throw new DomainException('Only system admins can set school discounts.');$schoolId=(int)($_POST['school_id']??0);$discount=filter_var($_POST['discount_percent']??null,FILTER_VALIDATE_FLOAT);$reason=trim((string)($_POST['reason']??''));
            if($discount===false||$discount<0||$discount>100||strlen($reason)>255)throw new DomainException('Enter a discount from 0 to 100 percent and a reason up to 255 characters.');$q=$pdo->prepare('SELECT id,name FROM schools WHERE id=?');$q->execute([$schoolId]);$school=$q->fetch(PDO::FETCH_ASSOC);if(!$school)throw new DomainException('Choose a valid school.');
            $pdo->beginTransaction();$q=$pdo->prepare('SELECT id,discount_percent,reason,active FROM school_subscription_discounts WHERE school_id=? FOR UPDATE');$q->execute([$schoolId]);$before=$q->fetch(PDO::FETCH_ASSOC);
            if($before){$q=$pdo->prepare('UPDATE school_subscription_discounts SET discount_percent=?,reason=?,active=? ,updated_by=? WHERE school_id=?');$q->execute([$discount,$reason?:null,$discount>0?1:0,$uid,$schoolId]);$discountId=(int)$before['id'];}else{$q=$pdo->prepare('INSERT INTO school_subscription_discounts (school_id,discount_percent,reason,active,updated_by) VALUES (?,?,?,?,?)');$q->execute([$schoolId,$discount,$reason?:null,$discount>0?1:0,$uid]);$discountId=(int)$pdo->lastInsertId();}
            $q=$pdo->prepare('INSERT INTO audit_logs (actor_id,action,entity_type,entity_id,details) VALUES (?,?,?,?,?)');$q->execute([$uid,$before?'update':'create','school_subscription_discount',$discountId,json_encode(['school_id'=>$schoolId,'school'=>$school['name'],'before'=>$before,'after'=>['discount_percent'=>$discount,'reason'=>$reason,'active'=>$discount>0]])]);$pdo->commit();header('Location: subscriptions.php?discount=saved');exit;
        }
        if($action==='subscribe'){
            if($role!=='director')throw new DomainException('Only directors can request a school subscription.');$schoolId=(int)($_POST['school_id']??0);$priceId=(int)($_POST['price_id']??0);$academicYear=filter_var($_POST['academic_year']??null,FILTER_VALIDATE_INT);
            if($academicYear===false||$academicYear<2000||$academicYear>2100)throw new DomainException('Choose a valid academic year.');
            $q=$pdo->prepare("SELECT s.id FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE s.id=? AND m.user_id=? AND m.scope='manager'");$q->execute([$schoolId,$uid]);if(!$q->fetchColumn())throw new DomainException('Choose a school linked to your director account.');
            $q=$pdo->prepare('SELECT id,billing_period,amount,currency,name FROM subscription_prices WHERE id=? AND active=1');$q->execute([$priceId]);$plan=$q->fetch(PDO::FETCH_ASSOC);if(!$plan)throw new DomainException('Choose an active subscription plan.');
            $q=$pdo->prepare("SELECT COUNT(*) FROM subscriptions WHERE school_id=? AND status IN ('active','pending') AND ends_on>=CURRENT_DATE");$q->execute([$schoolId]);if((int)$q->fetchColumn()>0)throw new DomainException('This school already has an active or pending subscription.');
            $q=$pdo->prepare("SELECT COUNT(*) FROM pupils WHERE school_id=? AND status='active'");$q->execute([$schoolId]);$pupilCount=(int)$q->fetchColumn();if($pupilCount<1)throw new DomainException('This school needs at least one active pupil before subscribing.');
            $q=$pdo->prepare('SELECT discount_percent FROM school_subscription_discounts WHERE school_id=? AND active=1');$q->execute([$schoolId]);$discountPercent=(float)($q->fetchColumn()?:0);$unitPrice=(float)$plan['amount'];$totalAmount=round($pupilCount*$unitPrice*(1-$discountPercent/100),2);
            $start=new DateTimeImmutable('today');$end=$start->modify($plan['billing_period']==='termly'?'+3 months':($plan['billing_period']==='yearly'?'+1 year':'+1 month'))->modify('-1 day');
            $pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO subscriptions (school_id,price_id,starts_on,ends_on,academic_year,pupil_count,unit_price,discount_percent,total_amount,status,created_by) VALUES (?,?,?,?,?,?,?,?,?,'pending',?)");$q->execute([$schoolId,$priceId,$start->format('Y-m-d'),$end->format('Y-m-d'),$academicYear,$pupilCount,$unitPrice,$discountPercent,$totalAmount,$uid]);$subId=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO audit_logs (actor_id,action,entity_type,entity_id,details) VALUES (?,?,?,?,?)');$q->execute([$uid,'request','subscription',$subId,json_encode(['school_id'=>$schoolId,'price_id'=>$priceId,'plan'=>$plan['name'],'currency'=>$plan['currency'],'academic_year'=>$academicYear,'pupil_count'=>$pupilCount,'unit_price'=>$unitPrice,'discount_percent'=>$discountPercent,'total_amount'=>$totalAmount,'starts_on'=>$start->format('Y-m-d'),'ends_on'=>$end->format('Y-m-d'),'status'=>'pending'])]);$pdo->commit();header('Location: subscriptions.php?subscribed=1');exit;
        }
        throw new DomainException('Unknown subscription action.');
    }catch(DomainException $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex->getMessage();}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error='The subscription action could not be saved. Apply the latest database schema and try again.';}
}

$prices=$pdo->query('SELECT * FROM subscription_prices ORDER BY active DESC,billing_period,name')->fetchAll(PDO::FETCH_ASSOC);
$analysisYear=filter_var($_GET['year']??date('Y'),FILTER_VALIDATE_INT);if($analysisYear===false||$analysisYear<2000||$analysisYear>2100)$analysisYear=(int)date('Y');$incomeRows=[];$pendingSubscriptions=[];$activeRows=[];$expiredCount=0;
if($isSystem){$q=$pdo->prepare("SELECT p.currency,COUNT(*) subscription_count,SUM(x.total_amount) income,SUM(x.pupil_count) pupils FROM subscriptions x JOIN subscription_prices p ON p.id=x.price_id WHERE x.status='active' AND x.academic_year=? GROUP BY p.currency ORDER BY p.currency");$q->execute([$analysisYear]);$incomeRows=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT x.id,s.name school_name,p.name plan_name,p.currency,p.billing_period,x.academic_year,x.pupil_count,x.unit_price,x.discount_percent,x.total_amount,x.starts_on,x.ends_on,DATEDIFF(x.ends_on,x.starts_on)+1 duration_days,DATEDIFF(x.ends_on,CURRENT_DATE) days_left FROM subscriptions x JOIN schools s ON s.id=x.school_id JOIN subscription_prices p ON p.id=x.price_id WHERE x.status='active' AND x.academic_year=? AND x.ends_on>=CURRENT_DATE ORDER BY x.ends_on,x.id");$q->execute([$analysisYear]);$activeRows=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT x.id,s.name school_name,p.name plan_name,p.currency,p.billing_period,x.academic_year,x.pupil_count,x.discount_percent,x.total_amount,x.starts_on,x.ends_on,DATEDIFF(x.ends_on,x.starts_on)+1 duration_days FROM subscriptions x JOIN schools s ON s.id=x.school_id JOIN subscription_prices p ON p.id=x.price_id WHERE x.status='pending' AND x.academic_year=? ORDER BY x.created_at");$q->execute([$analysisYear]);$pendingSubscriptions=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT COUNT(*) FROM subscriptions WHERE academic_year=? AND (status='expired' OR (status='active' AND ends_on<CURRENT_DATE))");$q->execute([$analysisYear]);$expiredCount=(int)$q->fetchColumn();}
$subAdmins=$isSystem?$pdo->query("SELECT u.id,u.name,u.email,COALESCE(p.active,0) price_edit FROM users u LEFT JOIN subscription_price_permissions p ON p.user_id=u.id WHERE u.role='sub_admin' AND u.status='active' ORDER BY u.name")->fetchAll(PDO::FETCH_ASSOC):[];
$schools=[];$subscriptions=[];$schoolDiscounts=[];
if($role==='director'){$q=$pdo->prepare("SELECT s.id,s.name,(SELECT COUNT(*) FROM pupils p WHERE p.school_id=s.id AND p.status='active') pupil_count,COALESCE((SELECT d.discount_percent FROM school_subscription_discounts d WHERE d.school_id=s.id AND d.active=1),0) discount_percent FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? AND m.scope='manager' ORDER BY s.name");$q->execute([$uid]);$schools=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT s.name school_name,p.name plan_name,p.currency,p.billing_period,x.academic_year,x.pupil_count,x.unit_price,x.discount_percent,x.total_amount,x.starts_on,x.ends_on,x.status FROM subscriptions x JOIN schools s ON s.id=x.school_id JOIN subscription_prices p ON p.id=x.price_id JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? AND m.scope=\'manager\' ORDER BY x.created_at DESC');$q->execute([$uid]);$subscriptions=$q->fetchAll(PDO::FETCH_ASSOC);}
if($isSystem)$schoolDiscounts=$pdo->query("SELECT s.id,s.name,(SELECT COUNT(*) FROM pupils p WHERE p.school_id=s.id AND p.status='active') pupil_count,d.discount_percent,d.reason,d.active FROM schools s LEFT JOIN school_subscription_discounts d ON d.school_id=s.id ORDER BY s.name")->fetchAll(PDO::FETCH_ASSOC);
if(isset($_GET['saved']))$notice=$_GET['saved']==='create'?'Per-pupil subscription price created and recorded in the audit log.':'Per-pupil subscription price updated and recorded in the audit log.';elseif(isset($_GET['permission']))$notice='Sub admin price management permission '.e((string)$_GET['permission']).'.';elseif(isset($_GET['subscribed']))$notice='Subscription request saved as pending.';elseif(isset($_GET['discount']))$notice='School discount saved and recorded in the audit log.';elseif(isset($_GET['confirmed']))$notice='Payment confirmation saved; the subscription is now included in income analysis.';
$editId=(int)($_GET['edit']??0);$editPrice=null;if($editId&&$canEdit){foreach($prices as $price){if((int)$price['id']===$editId){$editPrice=$price;break;}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Subscriptions · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item" href="schools.php">▦ &nbsp;Schools</a><a class="nav-item active" href="subscriptions.php" aria-current="page">◷ &nbsp;Subscriptions</a><?php if($isSystem||$role==='sub_admin'):?><a class="nav-item" href="audit.php">◷ &nbsp;Audit log</a><?php endif;?><?php if($isSystem):?><a class="nav-item" href="subscriptions.php#income">▤ &nbsp;Income analysis</a><?php endif;?><?php if($isSystem||$role==='sub_admin'):?><a class="nav-item" href="requests.php">✉ &nbsp;Requests</a><?php endif;?></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Subscriptions</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">SUBSCRIPTION MANAGEMENT</div><h1><?= $role==='director'?'School subscriptions':'Subscription prices' ?></h1><p class="muted"><?= $role==='director'?'Choose a plan for a school you manage. Requests remain pending until payment is set up.':'Create plans and control which sub admins can manage pricing.' ?></p></div></section><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="notice success" role="status"><?=$notice?></div><?php endif;?>
<?php if($isSystem)require __DIR__.'/subscription_analysis_panel.php';?><?php if($role==='director'):?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">AVAILABLE PLANS</div><h2>Choose a subscription</h2></div></div><?php if(!$prices):?><div class="empty-state"><h3>No plans available yet</h3><p>Subscription options will appear here when plans are published.</p></div><?php else:?><div class="plan-grid"><?php foreach($prices as $p):if(!(bool)$p['active'])continue;?><article class="plan-card"><span class="count-pill"><?=e(ucfirst($p['billing_period']))?></span><h3><?=e($p['name'])?></h3><div class="plan-price"><?=e($p['currency'])?> <?=e(number_format((float)$p['amount'],2))?></div><p class="muted">per pupil · per <?=e(rtrim($p['billing_period'],'ly'))?></p><?php if($schools):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="subscribe"><input type="hidden" name="price_id" value="<?=$p['id']?>"><label for="year-<?=$p['id']?>">Academic year for this pupil count</label><input id="year-<?=$p['id']?>" name="academic_year" type="number" min="2000" max="2100" value="<?=date('Y')?>" required><label for="school-<?=$p['id']?>">School</label><select id="school-<?=$p['id']?>" name="school_id" required><option value="">Choose a school</option><?php foreach($schools as $s):?><option value="<?=$s['id']?>" data-pupils="<?=$s['pupil_count']?>" data-discount="<?=$s['discount_percent']?>"><?=e($s['name'])?> · <?=$s['pupil_count']?> active pupils<?=((float)$s['discount_percent']>0?' · '.e((string)$s['discount_percent']).'% discount':'')?></option><?php endforeach;?></select><p class="muted">Estimate: <strong data-subscription-estimate>Select a school</strong></p><button class="button primary" type="submit">Request subscription</button></form><?php else:?><p class="muted">No schools are linked to your director account.</p><?php endif;?></article><?php endforeach;?></div><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">HISTORY</div><h2>Your school subscriptions</h2></div></div><?php if(!$subscriptions):?><p class="muted">No subscription requests yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Academic year</th><th>Plan</th><th>Pupils</th><th>Discount</th><th>Charge</th><th>Dates</th><th>Status</th></tr></thead><tbody><?php foreach($subscriptions as $s):?><tr><td><?=e($s['school_name'])?></td><td><?=e((string)$s['academic_year'])?></td><td><?=e($s['plan_name'])?> · <?=e($s['currency'])?> <?=e(number_format((float)$s['unit_price'],2))?>/pupil/period</td><td><?=number_format((int)$s['pupil_count'])?></td><td><?=e(number_format((float)$s['discount_percent'],2))?>%</td><td><?=e($s['currency'])?> <?=e(number_format((float)$s['total_amount'],2))?></td><td><?=e($s['starts_on'])?> – <?=e($s['ends_on'])?></td><td><?=e(ucfirst($s['status']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php else:?><?php if($canEdit):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow"><?= $editPrice?'UPDATE':'CREATE' ?></div><h2><?= $editPrice?'Update subscription price':'Create a subscription price' ?></h2></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_price"><input type="hidden" name="id" value="<?=e((string)($editPrice['id']??0))?>"><div class="form-grid"><div><label for="price-name">Plan name</label><input id="price-name" name="name" maxlength="100" required value="<?=e((string)($editPrice['name']??''))?>"></div><div><label for="amount">Price per pupil, per billing period</label><input id="amount" type="number" name="amount" min="0.01" step="0.01" required value="<?=e((string)($editPrice['amount']??''))?>"></div><div><label for="currency">Currency</label><input id="currency" name="currency" maxlength="3" minlength="3" required value="<?=e((string)($editPrice['currency']??'KES'))?>"></div><div><label for="period">Billing period</label><select id="period" name="billing_period"><option value="monthly" <?=($editPrice['billing_period']??'')==='monthly'?'selected':''?>>Monthly</option><option value="termly" <?=($editPrice['billing_period']??'')==='termly'?'selected':''?>>Termly</option><option value="yearly" <?=($editPrice['billing_period']??'yearly')==='yearly'?'selected':''?>>Yearly</option></select></div></div><label class="check-row"><input type="checkbox" name="active" value="1" <?=!$editPrice||$editPrice['active']?'checked':''?>> Available to directors</label><button class="button primary" type="submit"><?=$editPrice?'Save price changes':'Create price'?></button><?php if($editPrice):?><a class="button" href="subscriptions.php">Cancel</a><?php endif;?></form></section><?php else:?><div class="notice">Price management is permission gated. A system admin can grant access to your account.</div><?php endif;?>
<section class="content-section"><div class="section-heading"><div><div class="eyebrow">CATALOG</div><h2>Subscription plans</h2></div><span class="count-pill"><?=count($prices)?> plans</span></div><?php if(!$prices):?><p class="muted">No subscription prices created.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Plan</th><th>Rate per pupil</th><th>Billing</th><th>Director access</th><?php if($canEdit):?><th>Action</th><?php endif;?></tr></thead><tbody><?php foreach($prices as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['currency'])?> <?=e(number_format((float)$p['amount'],2))?> / pupil</td><td><?=e(ucfirst($p['billing_period']))?></td><td><?= $p['active']?'Available':'Hidden' ?></td><?php if($canEdit):?><td><a class="button" href="subscriptions.php?edit=<?=$p['id']?>">Edit</a></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if($isSystem):?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">SCHOOL DISCOUNTS</div><h2>Per-school discounts</h2><p class="muted">Set a percentage discount for each school. It is applied to that school’s per-pupil subscription total.</p></div></div><?php if(!$schoolDiscounts):?><p class="muted">Register a school before setting discounts.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Active pupils</th><th>Discount</th><th>Reason</th><th>Update discount</th></tr></thead><tbody><?php foreach($schoolDiscounts as $schoolDiscount):?><tr><td><?=e($schoolDiscount['name'])?></td><td><?=number_format((int)$schoolDiscount['pupil_count'])?></td><td><?=((bool)$schoolDiscount['active'])?e(number_format((float)$schoolDiscount['discount_percent'],2)).'%':'—'?></td><td><?=e($schoolDiscount['reason']?:'—')?></td><td><form method="post" class="school-discount-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="school_discount"><input type="hidden" name="school_id" value="<?=$schoolDiscount['id']?>"><label class="visually-hidden" for="discount-<?=$schoolDiscount['id']?>">Discount percent for <?=e($schoolDiscount['name'])?></label><input id="discount-<?=$schoolDiscount['id']?>" type="number" name="discount_percent" min="0" max="100" step="0.01" value="<?=e((string)($schoolDiscount['discount_percent']??0))?>" required><input name="reason" maxlength="255" placeholder="Reason (optional)" value="<?=e((string)($schoolDiscount['reason']??''))?>"><button class="button" type="submit">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?><?php if($isSystem):?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ACCESS CONTROL</div><h2>Sub admin price permissions</h2><p class="muted">Only system admins can grant or revoke price editing.</p></div></div><?php if(!$subAdmins):?><p class="muted">No active sub admin accounts.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Sub admin</th><th>Email</th><th>Price editing</th><th>Action</th></tr></thead><tbody><?php foreach($subAdmins as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email']?:'—')?></td><td><?=$u['price_edit']?'Granted':'Not granted'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="permission"><input type="hidden" name="user_id" value="<?=$u['id']?>"><input type="hidden" name="enabled" value="<?=$u['price_edit']?'0':'1'?>"><button class="button" type="submit"><?=$u['price_edit']?'Revoke':'Grant'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?><?php endif;?></div></main></div><script>document.querySelectorAll('.plan-card form').forEach(function(form){const select=form.querySelector('select[name="school_id"]');const estimate=form.querySelector('[data-subscription-estimate]');if(!select||!estimate)return;const unit=Number(form.querySelector('input[name="price_id"]').closest('.plan-card').querySelector('.plan-price').textContent.replace(/[^0-9.]/g,''));const currency=form.querySelector('input[name="price_id"]').closest('.plan-card').querySelector('.plan-price').textContent.trim().split(/\s+/)[0];select.addEventListener('change',function(){const option=select.options[select.selectedIndex];if(!option.value){estimate.textContent='Select a school';return}const pupils=Number(option.dataset.pupils||0);const discount=Number(option.dataset.discount||0);const total=pupils*unit*(1-discount/100);estimate.textContent=currency+' '+total.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+' per '+select.closest('.plan-card').querySelector('.muted').textContent.replace('per pupil · per ','')+' ('+pupils+' pupils, '+discount+'% discount)';});});</script></body></html>
